#include "result_schema.h"

Z6ResultJson& Z6ResultJson::operator=(const Z6ResultJson& other) {
    if (this != &other) {
        report_ = other.report_;
        report_valid_ = other.report_valid_;
        players_ = other.players_;
        players_valid_ = other.players_valid_;
    }
    return *this;
}

bool Z6ResultJson::validate(const std::string& json_str) {
    try {
        auto j = json::parse(json_str);
        if (!j.is_object()) return false;
        if (!j.contains("NAME")) return false;
        if (!j.contains("LEVEL")) return false;
        if (j.contains("Report")) {
            if (!j["Report"].is_string()) return false;
        }
        if (j.contains("Players")) {
            if (!j["Players"].is_array()) return false;
        }
        return true;
    } catch (...) {
        return false;
    }
}

bool Z6ResultJson::getReport(std::string& val) const {
    if (!report_valid_) return false;
    val = report_;
    return true;
}

bool Z6ResultJson::getPlayers(size_t index, std::string& val) const {
    if (!players_valid_ || index >= players_.size()) return false;
    val = players_[index];
    return true;
}

bool Z6ResultJson::getPlayersVector(std::vector<std::string>& val) const {
    if (!players_valid_) return false;
    val = players_;
    return true;
}

void Z6ResultJson::setReport(const std::string& val) {
    report_ = val;
    report_valid_ = true;
}

void Z6ResultJson::setPlayers(const std::vector<std::string>& val) {
    players_ = val;
    players_valid_ = true;
}

void Z6ResultJson::from_json(const std::string& json_str) {
    json j = json::parse(json_str);
        if (j.contains("Report")) {
            report_ = j["Report"];
            report_valid_ = true;
        }
        if (j.contains("Players")) {
            players_ = j["Players"].get<std::vector<std::string>>();
            players_valid_ = true;
        }
}

std::string Z6ResultJson::to_json() const {
    json j;
        if (report_valid_) {
            j["Report"] = report_;
        }
        if (players_valid_) {
            j["Players"] = players_;
        }
    return j.dump();
}

